 document.querySelectorAll('[data-param]').forEach(input=>input.onchange=e=>{const key=e.target.dataset.param,value=Number(e.target.value),[min,max]=PARAM_RANGES[c.type][key];if(e.target.value===''||!Number.isFinite(value)||value<min||value>max){toast(key+' 적용 범위 '+min+'…'+max+' 밖입니다.');render();return;}checkpoint();c.params[key]=value;changed()});
