function remove(){if(!selected)return;checkpoint();d.components=d.components.filter(c=>c.id!==selected);d.nets=d.nets.filter(n=>n.id!==selected&&n.a.component!==selected&&n.b.component!==selected);if(isPackage(d)){d.package.fau.mapping=d.package.fau.mapping.filter(m=>m.output!==selected);delete d.package.heaters[selected];}if(isWDM(d)||isPhysical(d)&&d.physical.architecture==='wdm'){d.wdm.tiles=d.wdm.tiles.filter(t=>![t.mux,t.output,t.driver,...t.modulators].includes(selected));d.wdm.arrays=d.wdm.arrays.filter(a=>!a.components.includes(selected));d.wdm.io.mapping=d.wdm.io.mapping.filter(m=>m.output!==selected);}if(d.scaling){d.scaling.tiles=d.scaling.tiles.filter(t=>![t.modulator,t.output,t.driver].includes(selected));d.scaling.arrays=d.scaling.arrays.filter(a=>!a.components.includes(selected));}selected=null;pending=null;changed()}
for(const [type,l]of Object.entries(LIB)){const b=document.createElement('button');b.className='component';b.style.setProperty('--color',l.color);b.draggable=true;b.dataset.type=type;b.innerHTML=esc(l.name)+'<span>'+l.w/100+' × '+l.h/100+' mm · '+(PACKETS[type]?'Generic EIC · RF out / 1ch · '+PACKETS[type].convention+' · Bias '+PACKETS[type].biasRange.join('…')+' V · '+PACKETS[type].platforms.join('/') : MOD_TYPES.includes(type)?'25 GBd NRZ · Optical in/out · RF in · '+modInfo({type}).drive.toFixed(2)+' '+modInfo({type}).convention+' V · Bias '+(type==='mzm'?'π/2':type==='mrm'?'−1 V':'−1.5 V')+' · '+modInfo({type}).platform+'<br>'+ (type==='mrm'?'Off-res IL 1 dB · Heater / Wavelength-sensitive':type==='eam'?'Bias-dependent Absorption · GeSi integration':'IL 3 dB nominal · Length / Bias-sensitive'):type==='laser'?'1310 nm O-band · Input 13 dBm · Optical out':'Optical')+'<br>Educational · Assumed'+'</span>';b.onclick=()=>{placing=type;toast(l.name+' — Canvas에서 위치를 클릭하세요.')};b.ondragstart=e=>{e.dataTransfer.setData('text/plain',type);placing=type};$('palette').append(b);}
