$('board').addEventListener('pointerdown',e=>{const p=point(e);if(space||e.button===1){drag={pan:true,x:e.clientX,y:e.clientY,view:[...view]};$('board').setPointerCapture(e.pointerId);return;}if(placing){checkpoint();selected=add(d,placing,pos(p.x),pos(p.y)).id;placing=null;changed()}else{selected=null;pending=null;render()}});
$('board').addEventListener('pointerdown',e=>{if(addingWaypoint){e.preventDefault();e.stopImmediatePropagation();const n=d.nets.find(n=>n.id===addingWaypoint),p=point(e);addingWaypoint=null;if(n&&n.route.waypoints.length<32){checkpoint();n.route.waypoints.push({x:pos(p.x),y:pos(p.y)});changed();}else toast('Waypoint 최대 32개');return;}if(space||e.button===1){e.preventDefault();e.stopImmediatePropagation();drag={pan:true,x:e.clientX,y:e.clientY,view:[...view]};$('board').setPointerCapture(e.pointerId)}},true);
$('board').addEventListener('pointermove',e=>{if(!drag)return;if(drag.package){const z=packageObject(d,drag.id),p=point(e);if(!z)return;const dx=pos(p.x-drag.x),dy=pos(p.y-drag.y);if(!drag.historyStarted&&(dx||dy)){checkpoint();drag.historyStarted=true;}if(drag.resize){z.w=Math.max(10,Math.min(2000-z.x,drag.original.w+dx));z.h=Math.max(10,Math.min(1600-z.y,drag.original.h+dy));}else{z.x=Math.max(0,Math.min(1900,drag.original.x+dx));z.y=Math.max(0,Math.min(1500,drag.original.y+dy));}dirty=true;render();return;}if(drag.waypoint){const n=d.nets.find(n=>n.id===drag.id),p=point(e),value={x:pos(p.x),y:pos(p.y)},old=n.route.waypoints[drag.index];if(value.x!==old.x||value.y!==old.y){if(!drag.historyStarted){checkpoint();drag.historyStarted=true;}setWaypoint(d,n,drag.index,value);dirty=true;render();}return;}if(drag.pan){const rect=$('board').getBoundingClientRect(),scale=Math.max(view[2]/rect.width,view[3]/rect.height);view[0]=drag.view[0]-(e.clientX-drag.x)*scale;view[1]=drag.view[1]-(e.clientY-drag.y)*scale;render();return}const c=d.components.find(c=>c.id===drag.id),p=point(e);const nx=pos(p.x-drag.x),ny=pos(p.y-drag.y);if(nx!==c.x||ny!==c.y){if(!drag.historyStarted){checkpoint();drag.historyStarted=true;}c.x=nx;c.y=ny;dirty=true;render()}});
$('board').addEventListener('pointerup',()=>{if(drag?.historyStarted)changed();drag=null});$('board').addEventListener('pointercancel',()=>{if(drag?.historyStarted)changed();drag=null});$('board').addEventListener('wheel',e=>{e.preventDefault();const p=point(e),factor=e.deltaY>0?1.12:.89,w=Math.max(300,Math.min(2500,view[2]*factor)),f=w/view[2];view=[p.x+(view[0]-p.x)*f,p.y+(view[1]-p.y)*f,w,view[3]*f];render()},{passive:false});
$('undo').onclick=()=>{if(history.length){future.push(clone(d));d=history.pop();selected=null;changed()}};$('redo').onclick=()=>{if(future.length){history.push(clone(d));d=future.pop();selected=null;changed()}};$('resetview').onclick=()=>{view=isScaling(d)?[-50,-70,2100,1700]:[-50,-70,1100,790];render()};$('fit').onclick=()=>{if(isPhysical(d)){view=[-50,-50,d.physical.die.width+100,d.physical.die.height+100];render();return;}if(isPackage(d)){view=[-60,-60,d.package.width+120,d.package.height+120];render();return;}if(!d.components.length)return $('resetview').click();const xs=d.components.map(c=>c.x),ys=d.components.map(c=>c.y),right=Math.max(...d.components.map(c=>c.x+definition(c).w)),bottom=Math.max(...d.components.map(c=>c.y+definition(c).h));view=[Math.min(...xs)-60,Math.min(...ys)-60,Math.max(400,right-Math.min(...xs)+120),Math.max(300,bottom-Math.min(...ys)+120)];render()};$('grid').onclick=()=>{snap=!snap;$('grid').textContent='Snap '+(snap?'ON':'OFF')};
document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)||$('modal').open)return;if(e.code==='Space'){space=true;e.preventDefault()}if(e.key==='Escape'){placing=null;pending=null;addingWaypoint=null;render()}if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();remove()}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();$(e.shiftKey?'redo':'undo').click()}const c=d.components.find(c=>c.id===selected),delta={ArrowLeft:[-1,0],ArrowRight:[1,0],ArrowUp:[0,-1],ArrowDown:[0,1]}[e.key];if(c&&delta){e.preventDefault();checkpoint();c.x+=delta[0]*(e.shiftKey?1:10);c.y+=delta[1]*(e.shiftKey?1:10);changed()}});document.addEventListener('keyup',e=>{if(e.code==='Space')space=false});
$('run').onclick=()=>{result=solve(d);dirty=false;if(d.brief==='rf'&&!d.challenge&&result.status==='VALID')beginRF(d);if(challengeProgress(d,result).complete&&!d.completedLevels.includes(d.brief)){d.completedLevels.push(d.brief);scheduleSave();}result.goalScore=solutionAssessment(d,result).score;lastTestDesign=clone(d);render();toast(challengeProgress(d,result).complete?'Level 목표 달성! '+result.gross+'G · '+(isScaling(d)?'Architecture Metrics':'Goal Score '+result.goalScore):result.gross+' Gb/s 활성 · 진단 항목에서 수정할 위치를 확인하세요.')};$('save').onclick=persist;
function modal(html){$('modalContent').innerHTML=html;$('modal').showModal()}$('closemodal').onclick=()=>$('modal').close();
$('models').onclick=()=>modal(`${isPhysical(d)?'<h2>PHYSICAL PIC MODEL · v0.7.0</h2><p>DRC-lite / Educational Geometry. 100 canvas units =1mm. Circular 90° bends have exact arc length; effective R is min(requested R, half of adjacent segments). Bend loss per90° =0.01 exp(0.1/Rmm) dB; propagation0.12dB/mm. Physical geometric intersections each add0.03dB per traversal; overlap / parallel spacing failures are blocked. Single layer surrogate, no qualified crossing cell / multilayer model. 12 samples per90° arc support intersection and obstacle checks; spacing checks parallel straight corridors. No mask-edge DRC.</p><p>Total optical loss includes components, ideal splitter division, excess, actual propagation / bend / crossing, Mux and output coupling once. Minimum Bend0.04mm, parallel Spacing0.02mm, clearance0.04mm; all dimensions and coefficients are educational assumptions.</p><p>Filter Thermal: T=Ambient + sum(8P/[1+(distance/1mm)^2]) °C, reference25°C, shift0.08nm/K, supported ambient20–40°C. Applied to actual Mux transmission once. Require Filter T≤45°C and |shift|≤0.9nm. Separate from previous package / MRM models; high-speed junction response, FEM, BER, real GDS, PDK DRC/LVS Unsupported.</p><p>Score = weighted normalized optical margin, envelope, route efficiency, DRC compliance, robustness. Hard feasibility FAIL gives0 regardless of raw weighted score. Full equations / dimensions: docs/MODELS_V070.md and SCORE_V070.md.</p><hr><h3>Preserved engine models below</h3>':''}${isWDM(d)?'<h2>WDM MODEL1.0.0 · SOLVER0.6.0</h2><p>Educational O-band Grid:1304 /1308 /1312 /1316nm. No CWDM / LAN-WDM compliance. CW Source power is dBm per wavelength; Total = sum linear mW. One wavelength can feed four independent MZMs through actual1×4 division / excess / routes. WDM does not reduce Electrical Data Channel count.</p><p>Mux intensity T=10^(−IL/10)[f+(1−f)exp(−4 ln2(Δλ/FWHM)²)], f=10^(−isolation/10). Defaults IL2dB / FWHM2nm / floor30dB are assumed. Port-specific separation screen ≥18dB is not BER. The four optical levels are per wavelength; aggregate output is a linear average-power sum, not one PAM4 waveform.</p><p>Generic hs100 response is assumed wavelength-flat over1302–1318nm at25°C. Thermal wavelength drift / high-rate WDM junction response / Receiver / coherent effects are Unsupported. Optional FAU replaces edge loss once; allλ in a physical channel share its assembly offset. Existing surrogate is assumed wavelength-flat. No WDM yield/lifetime claim.</p><p>Primary structural evidence: <a href="https://www.nature.com/articles/s41598-024-69042-x" target="_blank" rel="noopener">O-band spectral filters, Scientific Reports2024</a> and OIF3.2T IA. Their measured curves and Ethernet rates are not these game coefficients. Full model and assumptions:docs/MODELS_V060.md.</p><hr><h3>Existing model scopes below</h3>':''}${isPackage(d)?'<h2>PACKAGE MODEL 1.1.0 · SOLVER 0.5.0</h2><p>Estimated steady-state temperature, Educational / Assumed. Tᵢ = Ambient + Σⱼ Rᵢⱼ Pⱼ. EIC self R=22 K/W, fixed MZM Heater self R=70 K/W; off-diagonal R=6/[1+(distance/2 mm)²] K/W. Cooling adds conductance G (W/K): Fᵢ=1/(1+RᵢᵢΣG); Rᵢⱼ→√(FᵢFⱼ)Rᵢⱼ. Nonnegative matrix, finite self term, no feedback iteration.</p><p>Generic EIC pole = nominal BW/[1+0.0015 max(T−25,0)]; loaded swing gain=1−0.002 max(T−25,0), lower bound 0.5. MZM bias shift=0.004(T−25)−0.002 Heater(mW) rad; excess loss=0.008 max(T−25,0) dB. These coefficients are fresh educational assumptions and are unrelated to the Level3 MRM resonance fit. Supported local temperature 20–120 °C; Customer hotspot limit 65 °C. Recompute all four PAM4 levels, residual and functional lane throughput.</p><p>FAU interface replaces legacy Edge Coupler loss. Compact:1.2 dB nominal / 2 µm lateral 1 dB radius / 2° angular scale. Expanded-mode:1.8 dB / 8 µm / 0.5°. Alignment penalty = (Δx²+Δy²)/tolerance² + (rotation/angular scale)² dB. Pitch rotation also introduces channel-position-dependent lateral error. Actual interface mode fields are unavailable: Educational Coupling Surrogate, not manufacturing accuracy.</p><p>Monte Carlo: common FAU X/Y and Rotation + residual per channel + common Ambient variation. Seeded zero-mean Normal profiles; actual solver reruns each sample. Wilson 95% interval is sampling uncertainty. Corner Test is eight explicit ±2σ Stress Scenarios. Simulated Assembly Pass Fraction is not measured yield or lifetime.</p><p>Primary structural references: <a href="https://doi.org/10.1364/OE.480418" target="_blank" rel="noopener">Optics Express detachable fiber I/O study</a>; <a href="https://www.oiforum.com/wp-content/uploads/OIF-Co-Packaging-3.2T-Module-01.0.pdf" target="_blank" rel="noopener">OIF 3.2T Packaging IA</a>. Their measured interfaces are not these game profiles. Full equations / boundaries / assumptions: docs/MODELS_V050.md.</p><hr>':''}${isScaling(d)&&!isPackage(d)?'<h2>SCALING MODEL 1.0.0 · SOLVER 0.4.1</h2><p>Generic educational 100G/50GBd and200G/100GBd PAM4; nominal25°C/1310nm. Four differential electrical symbols map through a sine MZM response to four optical powers. Adjacent gap/span, nonlinearity and a conservative three-pole tail proxy are planning screens, not BER/eye/TDECQ.</p><p>RF α(f)=0.35√(f/25)+0.05(f/25) dB/mm; driver/modulator/route first-order poles, three frequency samples. Route≤5mm; effective swing≥0.65Vppd; tail proxy≤0.65; gap/span≥0.22; average≥−4dBm; ER≥3dB. All coefficients are Assumed.</p><p>Each1×N stage:10log10(N)+excess dB; trace every actual optical graph edge. Electrical boundary:connected EIC channels plus all shared overhead; excludes laser, RX, DSP/FEC and cooling. pJ/bit uses functional gross rate. High-speed thermal is Unsupported.</p><p>Structural primary sources: Caltech100G PAM4 transmitter and Nature Electronics112GBd SiPh-CMOS transmitter. Their measured coefficients and reported energy are not the game assumptions; full URLs and boundaries are in docs/MODELS_V041.md.</p><hr><h3>Legacy Level1–5 models</h3>':''}<h2>MODELS · revision 0.2.1 · O-band</h2><p>Calculated는 Assumed Parameter로 계산했다는 뜻이며 Validated가 아닙니다. 본 게임은 Educational Grade입니다. Measured 값은 사용하지 않습니다.</p><p>MZM: Vπ=3.75 V·mm / Length; IL=1.5+Length dB; T±=10^(−IL/10)[1+cos(π Bias ±π Swing/(2Vπ))]/2.<br>MRM Cavity BW=31.44 GHz from 0.18 nm FWHM at 1310 nm. Through-port: T(Δ)=10^(−1/10)[1−0.95/(1+(Δ/0.09 nm)²)]. Δ에는 Cold Resonance, 0.08 nm/K, Bias shift 0.08 nm/V, Heater 0.01 nm/mW가 포함됩니다. Heater 0–80 mW, Auto Lock target +0.04 nm.<br>EAM: T(V)=10^(−[1+1.8|V|^1.5(1+0.02(λ−1310))]/10), V=Bias±Swing/2. 이는 Beer–Lambert 구조를 사용하는 가정된 Absorption Fit이며 O-band GeSi QCSE Device의 검증 모델이 아닙니다.</p><p>RF: 동일 Polyline Centerline 길이 × Packet α, Delivered Swing = Vout×10^(−Loss/20). Driver/Route/Modulator 1-pole response의 Nyquist amplitude를 별도로 두 Optical Level 계산에 적용합니다. BW ratio는 BER/Eye Margin이 아닙니다.</p><p>Average=(High+Low)/2, ER=10log10(High/Low), OMA=High−Low [mW]. NRZ equiprobable 0/1 assumption. Power 경계=Driver+Heater+EAM Bias, External Laser 제외. pJ/bit는 동일 Nominal 환경의 유효 Gross Rate를 분모로 사용합니다. Stable HUD의 Gross는 시험한 Corner 중 최솟값입니다. Net Throughput은 FEC/Protocol 미모델링으로 Unsupported입니다.</p><p>Thermal: Ambient+각 Driver의 6 K/W 거리 Kernel+이웃 Heater의 40 K/W Kernel. Self Heater는 Resonance 효율로 처리합니다. FEM이 아닌 Educational Approximation입니다.</p><p>Primary Sources: <a href="https://www.nature.com/articles/nphoton.2017.120" target="_blank">MZM VπL trade-off</a> · <a href="https://www.nature.com/articles/s41467-024-45301-3" target="_blank">MRM voltage / heater response</a> · <a href="https://imec-publications.be/entities/publication/def47af9-9bb6-4d64-adef-533d86b5112d" target="_blank">O-band GeSi QCSE EAM</a>. 수치·Geometry는 논문 제품 사양이 아닌 교육용 가정입니다.</p><p>Routing v0.3.0: Optical은 Sharp Orthogonal Centerline, RF는 Polyline입니다. Optical Loss=0.12 dB/mm×Length+0.04 dB×Bend (기존 Assumed 계수). 반경·Cross-section·RF Bend Reflection·물리 Crossing Loss는 Unsupported입니다. Keep-out / Component 내부 / Boundary는 Planning Rule Check이며 DRC가 아닙니다.<br>적용 범위: 25 GBd NRZ, MZM 0.8–2.5 mm, RF ≤10 mm, Ambient 20–60 °C, Laser 1309–1311 nm. Unsupported: BER/Eye, Full-wave, DRC, Thermal FEM, GDS. Score는 유효 설계에서 max(0,100−20×Power W−2×Footprint mm²)이며 비교표가 우선입니다.</p>`);
function download(name,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
$('files').onclick=async()=>{let names=[];if(ready)names=await storage.read('names')||[];modal(`<h2>DESIGN SAVE / LOAD / EXPORT</h2><label>Design name <input id="rename" value="${esc(d.name)}"></label><div class="row"><button id="namedSave">별도 저장</button><select id="savedDesign">${names.map(n=>`<option>${esc(n)}</option>`).join('')}</select><button id="namedLoad">불러오기</button><button id="recover">Backup 복구</button></div><div class="row"><button id="json">JSON Export</button><button id="png">Floorplan PNG</button><button id="summary">Summary</button></div><p>JSON을 붙여넣으면 업로드 없이 복원할 수 있습니다. Import 실패 시 현재 Design은 유지됩니다.</p><textarea id="jsonText" placeholder="Paste Design JSON"></textarea><button id="import">검증 후 Import</button>`);$('rename').onchange=e=>{checkpoint();d.name=e.target.value.slice(0,100)||'Untitled';changed()};$('json').onclick=async()=>download('photonics-design.json',JSON.stringify({schema:d.schema,routeModelVersion:'0.3.0',solverVersion:solve(d).version,modelVersion:'0.2.1',models:Object.values(LIB).map(l=>({id:l.id,version:l.version,grade:l.grade,evidence:l.evidence})),design:exportDesign(d),referenceBackup:studio?.exportBackup(),campaignArchive:campaignUI?.exportArchive(),wdmOriginals:await wdmUI?.exportOriginals(),physicalOriginals:physicalUI?.exportOriginals(),chapterWorkspaces:await chapterUI?.exportState()},null,2));$('summary').onclick=()=>download('engineering-summary.json',JSON.stringify({design:d.name,assumption:'Generic Educational Model',solver:solve(d),modelVersion:'0.2.1',unsupported:['BER','DRC','GDS']},null,2));$('import').onclick=async()=>{try{const raw=JSON.parse($('jsonText').value),next=validateImport(raw),importBackup=studio?.prepareBackup(raw.referenceBackup),importArchive=Object.hasOwn(raw,'campaignArchive')?campaignUI?.prepareArchive(raw.campaignArchive):null,importWDMOriginals=Object.hasOwn(raw,'wdmOriginals')?wdmUI?.prepareOriginals(raw.wdmOriginals):null;const importPhysicalOriginals=Object.hasOwn(raw,'physicalOriginals')?physicalUI?.prepareOriginals(raw.physicalOriginals):null;const importChapters=raw.chapterWorkspaces?chapterUI.prepare(raw.chapterWorkspaces):null;if(ready)await storage.archiveOriginal(raw.design??raw);if(ready&&(raw.design??raw).modelVersion==='0.2.0')await storage.archiveLegacy(raw.design??raw);if(raw.referenceBackup&&studio)await studio.importBackup(importBackup);if(importArchive)await campaignUI.importArchive(importArchive);if(importWDMOriginals)await wdmUI.importOriginals(importWDMOriginals);if(importPhysicalOriginals)await physicalUI.importOriginals(importPhysicalOriginals);checkpoint();d=next;selected=null;pending=null;changed();if(importChapters)await chapterUI.importState(importChapters);$('modal').close();toast(next.nets.find(n=>n.route?.recoveryNotice)?.route.recoveryNotice||d.migrationNotice||'Design 검증 및 복원 완료')}catch(e){toast('Import 거부: '+e.message)}};$('namedSave').onclick=async()=>{if(!ready)return toast('저장 불가. JSON Export를 사용하세요.');try{await persist();await storage.write('named:'+d.name,clone(d));await storage.write('names',[...new Set([...names,d.name])]);toast('별도 저장 완료')}catch(e){toast('저장 실패: '+e.message)}};$('namedLoad').onclick=async()=>{try{const next=validateImport(await storage.read('named:'+$('savedDesign').value));checkpoint();d=next;selected=null;changed();$('modal').close()}catch(e){toast('불러오기 실패: '+e.message)}};$('recover').onclick=async()=>{try{const next=validateImport(await storage.read('backup'));checkpoint();d=next;selected=null;changed();$('modal').close()}catch(e){toast('Backup 복구 실패: '+e.message)}};$('png').onclick=exportPNG;};
function exportPNG(){const svg=$('board').cloneNode(true);svg.setAttribute('xmlns',NS);svg.setAttribute('viewBox',[-20,-20,planningBounds(d).w+40,planningBounds(d).h+40].join(' '));svg.setAttribute('width',1600);svg.setAttribute('height',1062);svg.querySelectorAll('.flow,.waypoint,.route-hit').forEach(e=>e.remove());const exportStyle=document.createElementNS(NS,'style');exportStyle.textContent='text{font-family:system-ui,sans-serif}.net{fill:none;stroke-width:3}.route-invalid{stroke:#ff7c88;stroke-dasharray:7 4}.port{stroke:#0d1625;stroke-width:3}.invalid .body{stroke:#ff647e;stroke-width:2}.route-label{fill:#f0f6ff;font-size:12px;paint-order:stroke;stroke:#091321;stroke-width:4}'+themeUI.exportStyle();svg.insertBefore(exportStyle,svg.firstChild);const url=URL.createObjectURL(new Blob([new XMLSerializer().serializeToString(svg)],{type:'image/svg+xml'})),image=new Image;image.onload=()=>{const canvas=document.createElement('canvas');canvas.width=1600;canvas.height=1062;const ctx=canvas.getContext('2d');ctx.fillStyle=themeUI.current()==='light'?'#f7f9fc':'#091321';ctx.fillRect(0,0,1600,1062);ctx.drawImage(image,0,0);canvas.toBlob(blob=>{const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='pic-floorplan.png';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)});URL.revokeObjectURL(url)};image.onerror=()=>toast('PNG Export 실패');image.src=url;}

for(const [id,key,min,max]of [['ambient','temperature',20,60],['wavelength','wavelength',1309,1311]])$(id).onchange=e=>{const value=Number(e.target.value);if(e.target.value===''||!Number.isFinite(value)||value<min||value>max){toast(key+' 적용 범위 '+min+'…'+max+' 밖');render();return;}checkpoint();d.environment[key]=value;changed()};
