$('compare').onclick=()=>{if(isPhysical(d))return physicalUI.compare();if(isWDM(d))return wdmUI.compare();if(isPackage(d))return packageUI.compare();if(isScaling(d))return scalingUI.compare();if(!d.snapshots.length&&!d.challenge?.baseline)return toast('Test 후 Snapshot을 먼저 저장하세요.');const options=(d.brief==='rf'&&d.challenge?.baseline?'<option value="baseline">RF Baseline</option>':'')+`<option value="current">Current · ${esc(d.name)}</option>`+d.snapshots.map((s,i)=>`<option value="${i}">${esc(s.name)}</option>`).join('');modal(`<h2>DESIGN COMPARISON</h2><div class="snapshot-row"><select id="compareA">${options}</select><span>vs</span><select id="compareB">${options}</select><button id="loadSnapshot">A Design 불러오기</button></div><div id="comparisonTable"></div>`);$('compareA').value=d.brief==='rf'&&d.challenge?.baseline?'baseline':String(Math.max(0,d.snapshots.length-1));$('compareB').value='current';function chosen(id){return $(id).value==='baseline'?d.challenge.baseline:$(id).value==='current'?capture(d,'Current'):d.snapshots[+$(id).value];}function update(){const a=chosen('compareA'),b=chosen('compareB');if(dirty&&[$('compareA').value,$('compareB').value].includes('current')){$('comparisonTable').innerHTML='<p>Current Result가 STALE입니다. 닫고 Test를 실행한 뒤 비교하세요.</p>';return;}const comparison=compareSnapshots(a,b),ra=comparison.a,rb=comparison.b;const laneList=(r,key,suffix)=>r.lanes.map((l,i)=>'L'+(i+1)+': '+fmt(l[key])+' '+suffix).join('<br>'),rfList=r=>r.lanes.map((l,i)=>'L'+(i+1)+': '+fmt(l.rf?.length)+' mm / '+fmt(l.rf?.swing)+' '+(l.rf?.convention||'')+' V / BW '+fmt(l.rf?.bwRatio)).join('<br>');const rows=[['Requirement Satisfaction',ra.status,rb.status],['Valid Lanes / Gross',ra.gross/25+' / '+ra.gross+' Gb/s',rb.gross/25+' / '+rb.gross+' Gb/s'],['Optical Average',laneList(ra,'power','dBm'),laneList(rb,'power','dBm')],['High / Low',ra.lanes.map(l=>fmt(l.highDbm)+' / '+fmt(l.lowDbm)+' dBm').join('<br>'),rb.lanes.map(l=>fmt(l.highDbm)+' / '+fmt(l.lowDbm)+' dBm').join('<br>')],['Extinction',laneList(ra,'er','dB'),laneList(rb,'er','dB')],['OMA (linear power)',laneList(ra,'omaMw','mW'),laneList(rb,'omaMw','mW')],['RF Length / Delivered / BW ratio',rfList(ra),rfList(rb)],['RF Total / Worst Route',fmt(ra.routing.rfTotal)+' / '+fmt(ra.routing.rfWorst)+' mm',fmt(rb.routing.rfTotal)+' / '+fmt(rb.routing.rfWorst)+' mm'],['RF Attenuation / Lane',ra.lanes.map(l=>fmt(l.rf?.loss)+' dB').join('<br>'),rb.lanes.map(l=>fmt(l.rf?.loss)+' dB').join('<br>')],['Optical Total / Worst Lane Length',fmt(ra.routing.opticalTotal)+' / '+fmt(Math.max(0,...ra.lanes.map(l=>l.optical?.length||0)))+' mm',fmt(rb.routing.opticalTotal)+' / '+fmt(Math.max(0,...rb.lanes.map(l=>l.optical?.length||0)))+' mm'],['Optical Propagation / Bend Loss per Lane',ra.lanes.map(l=>fmt(l.optical?.propagationLoss)+' / '+fmt(l.optical?.bendLoss)+' dB').join('<br>'),rb.lanes.map(l=>fmt(l.optical?.propagationLoss)+' / '+fmt(l.optical?.bendLoss)+' dB').join('<br>')],['Layout / Routing Errors',ra.routing.errorCount,rb.routing.errorCount],['Driver / Heater / Bias Power',Object.values(ra.powerBreakdown).slice(0,3).map(v=>fmt(v*1000)+' mW').join(' / '),Object.values(rb.powerBreakdown).slice(0,3).map(v=>fmt(v*1000)+' mW').join(' / ')],['Nominal Electrical Power / pJ per Nominal Gross bit',fmt(ra.powerW)+' W / '+fmt(ra.pjPerGrossBit),fmt(rb.powerW)+' W / '+fmt(rb.pjPerGrossBit)],['Footprint sum',fmt(ra.area)+' mm²',fmt(rb.area)+' mm²'],['Thermal / Detuning',ra.lanes.map(l=>fmt(l.temperature)+' °C / '+fmt(l.detuning,3)+' nm').join('<br>'),rb.lanes.map(l=>fmt(l.temperature)+' °C / '+fmt(l.detuning,3)+' nm').join('<br>')],['Variation Sensitivity',ra.variation.length?ra.variation.map(v=>fmt(v.environment.temperature)+' °C / '+fmt(v.environment.wavelength,3)+' nm · '+v.status+' · ERmin '+fmt(v.minEr)+' · '+fmt(v.powerW)+' W').join('<br>'):'Corner 미시험',rb.variation.length?rb.variation.map(v=>fmt(v.environment.temperature)+' °C / '+fmt(v.environment.wavelength,3)+' nm · '+v.status+' · ERmin '+fmt(v.minEr)+' · '+fmt(v.powerW)+' W').join('<br>'):'Corner 미시험'],['Environment / Solver',fmt(ra.environment.temperature)+' °C / '+fmt(ra.environment.wavelength,3)+' nm · '+a.solverVersion,fmt(rb.environment.temperature)+' °C / '+fmt(rb.environment.wavelength,3)+' nm · '+b.solverVersion],['Model Grade',ra.grade+' / '+ra.evidence,rb.grade+' / '+rb.evidence]];let reason=comparison.comparable?'동일 Brief·환경·Solver: 직접 비교 가능':'직접 비교 불가: '+(!comparison.sameEnvironment?'Brief 또는 환경이 다릅니다. ':'')+(!comparison.sameSolver?'Solver Version이 다릅니다. ':'');$('comparisonTable').innerHTML='<p>'+reason+' · 저장 Result를 신뢰하지 않고 Design을 현재 Solver로 재계산했습니다.</p><table><thead><tr><th>Metric</th><th>'+esc(a.name)+'</th><th>'+esc(b.name)+'</th><th>Δ B−A</th></tr></thead><tbody>'+rows.map(row=>{let delta='—';const pairs={'RF Total / Worst Route':[rb.routing.rfTotal-ra.routing.rfTotal,rb.routing.rfWorst-ra.routing.rfWorst,' mm'],'Optical Total / Worst Lane Length':[rb.routing.opticalTotal-ra.routing.opticalTotal,Math.max(0,...rb.lanes.map(l=>l.optical?.length||0))-Math.max(0,...ra.lanes.map(l=>l.optical?.length||0)),' mm'],'Footprint sum':[rb.area-ra.area,null,' mm²'],'Layout / Routing Errors':[rb.routing.errorCount-ra.routing.errorCount,null,''],'Nominal Electrical Power / pJ per Nominal Gross bit':[rb.powerW-ra.powerW,null,' W']};if(comparison.comparable&&pairs[row[0]]){const [v,w,unit]=pairs[row[0]];delta='<span class="'+(v<0?'delta-lower':v>0?'delta-higher':'')+'">'+(v>0?'+':'')+fmt(v)+(w!==null?' / '+(w>0?'+':'')+fmt(w):'')+unit+'</span>';}return '<tr>'+row.map(cell=>'<td>'+cell+'</td>').join('')+'<td>'+delta+'</td></tr>'}).join('')+'</tbody></table><p>'+ (comparison.comparable?'B−A: Footprint '+fmt(rb.area-ra.area)+' mm² · RF Total '+fmt(rb.routing.rfTotal-ra.routing.rfTotal)+' mm · Optical Total '+fmt(rb.routing.opticalTotal-ra.routing.opticalTotal)+' mm · Planning errors '+(rb.routing.errorCount-ra.routing.errorCount)+' · Power '+fmt((rb.powerW-ra.powerW)*1000)+' mW. Driver를 가까이 옮겼다면 Thermal / Detuning 변화도 확인하세요. 개선과 악화를 함께 비교합니다. Δ는 변화량이며 짧은 Route를 전체 Design의 승리로 평가하지 않습니다.':'동일 조건으로 Test한 Snapshot을 새로 저장하세요.')+'</p><p>Original Result A: '+esc(a.originalResult?.version||'미기록')+' / '+esc(a.originalResult?.status||'—')+' · B: '+esc(b.originalResult?.version||'미기록')+' / '+esc(b.originalResult?.status||'—')+' — 원본은 보존하며 표는 현재 Solver로 재계산합니다.</p>';}for(const id of ['compareA','compareB'])$(id).onchange=update;$('loadSnapshot').onclick=()=>{const a=chosen('compareA');checkpoint();const snapshots=clone(d.snapshots);d=validateImport(a.design);d.snapshots=snapshots;selected=null;pending=null;changed();$('modal').close();toast('Snapshot Design 복원. Test를 다시 실행하세요.')};update();};
